export async function voiceReference(action,value){return new Promise((resolve,reject)=>{const open=indexedDB.open('goku-local-voice',1);open.onupgradeneeded=()=>open.result.createObjectStore('reference');open.onerror=()=>reject(open.error);open.onsuccess=()=>{const db=open.result,tx=db.transaction('reference',action==='read'?'readonly':'readwrite'),store=tx.objectStore('reference');const request=action==='read'?store.get('selected'):action==='write'?store.put(value,'selected'):store.delete('selected');let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>{db.close();resolve(result)};tx.onerror=()=>{db.close();reject(tx.error)}}})}
